    landingFeature3Title: "बार पोर प्रणाली", landingFeature3Desc: "बोतल किन्नुहोस्, ग्लासमा बेच्नुहोस्। पोर ट्र्याक, स्टक कटौती, र प्रति ड्रिंक बिक्री।",
