    landingFeature5Title: "व्यापार स्वास्थ्य स्कोर", landingFeature5Desc: "०-१०० को स्कोर पाउनुहोस्। नाफा, निरन्तरता, लागत नियन्त्रण — एक नजरमा।",
    landingFeature6Title: "फोहोर ट्र्याकर", landingFeature6Desc: "म्याद सकिएको र बर्बाद भएको स्टक लग गर्नुहोस्। तपाईं कति गुमाइरहनुभएको छ हेर्नुहोस्।",
