    landingFeature8Title: "कार्यशाला व्यवस्थापन", landingFeature8Desc: "जब कार्ड, गाडी ट्र्याकिङ, पार्ट्स र श्रम बिलिङ, मेकानिक लिडरबोर्ड — अटो कार्यशालाको लागि।",
    landingFeature9Title: "बहु-व्यापार", landingFeature9Desc: "एउटा लगइनमा क्याफे र कार्यशाला चलाउनुहोस्। प्रत्येक शाखाको आफ्नै प्रकार, नेभिगेसन र दैनिक बन्द।",
